<?php
namespace App\Http\Controllers;
use App\Models\EmployeeContract; use App\Services\WorkforceAuditService; use Illuminate\Http\Request;
class ContractController extends Controller { public function index(){ $contracts=EmployeeContract::query()->latest('start_date')->paginate(30); return view('workforce.contracts.index',compact('contracts')); }
public function store(Request $r, WorkforceAuditService $audit){$d=$r->validate(['employee_id'=>'required|exists:employees,id','contract_type'=>'required|in:permanent,probation,fixed_term,part_time,hourly,locum,visiting,sessional','start_date'=>'required|date','end_date'=>'nullable|date|after_or_equal:start_date','probation_end_date'=>'nullable|date|after_or_equal:start_date','basic_salary'=>'nullable|numeric|min:0','hourly_rate'=>'nullable|numeric|min:0','session_rate'=>'nullable|numeric|min:0','patient_rate'=>'nullable|numeric|min:0','revenue_share_percent'=>'nullable|numeric|min:0|max:100','cost_centre_id'=>'nullable|exists:cost_centres,id','reference_no'=>'nullable|string|max:100','terms_summary'=>'nullable|string|max:3000']);$d['created_by']=auth()->id();$m=EmployeeContract::create($d);$audit->model('created',$m,'Employee contract created');return back()->with('success','Contract saved.');}}